# Quelle für src/data/quickcheck.json — Fragen des Quick-Checks (DE/EN).
# Gewicht: erste und letzte Frage 1.5, sonst 1. Antworten: Ja 100 / Teilweise 50 / Nein 0.
import json, pathlib

def Q(qid, ref_de, ref_en, q_de, q_en, why_de, why_en, rec_de, rec_en, w=1):
    return dict(id=qid, weight=w,
                ref=dict(de=ref_de, en=ref_en),
                q=dict(de=q_de, en=q_en),
                why=dict(de=why_de, en=why_en),
                rec=dict(de=rec_de, en=rec_en))

